#!/usr/bin/env bash
set -euo pipefail
repo_root="$(cd "$(dirname "$0")/../.." && pwd)"
output_dir="$(mktemp -d "$repo_root/.context/graphics-libc.XXXXXX")"
trap 'rm -rf "$output_dir"' EXIT
mkdir -p "$output_dir/include" "$output_dir/glue"
for name in EGL GLES2 KHR; do
    cp -R "$repo_root/libc/musl-overlay/include/$name" "$output_dir/include/"
done
cp "$repo_root/libc/musl-overlay/include/gbm.h" "$output_dir/include/"
cp "$repo_root/libc/glue/gbm_window.h" "$repo_root/libc/glue/wayland-native.h" "$output_dir/glue/"
for name in gl_abi.h libegl_stub.c libglesv2_stub.c; do
    if [ $# -eq 1 ]; then
        git -C "$repo_root" show "$1:libc/glue/$name" > "$output_dir/glue/$name"
    else
        cp "$repo_root/libc/glue/$name" "$output_dir/glue/$name"
    fi
done
clang -g -O1 -pthread -fsanitize="${KANDELO_GRAPHICS_SANITIZERS:-undefined}" -fno-omit-frame-pointer -fno-sanitize-recover=all \
    -I"$output_dir/include" -I"$output_dir/glue" \
    -include "$repo_root/tests/graphics/libc/device-double.h" \
    "$output_dir/glue/libegl_stub.c" "$output_dir/glue/libglesv2_stub.c" \
    "$repo_root/tests/graphics/libc/image-ownership.c" -o "$output_dir/image-ownership"
status=0
default_cases="native-fence-sync server-wait-basic server-wait-peer server-wait-errors server-wait-allocation server-wait-prefix server-wait-receipts server-wait-disposition server-wait-client-signal encoder-object-large-log encoder-object-chunk encoder-object-begin encoder-object-release encoder-object-magic encoder-object-count encoder-object-oom display-wayland display-wayland-window sync-khr-basic sync-khr-errors sync-khr-width sync-khr-lifetime sync-khr-render sync-basic sync-invalid sync-allocation sync-create-reject sync-create-unknown sync-create-malformed sync-submit-reject sync-wide sync-guard sync-render sync-status-errors sync-flush-current sync-flush-peer sync-timeout sync-release-unknown sync-session-reuse sync-terminated-create sync-destroy-wait sync-generation sync-cancel flush-ack core-image-render core-image-basic core-image-invalid core-image-wide core-image-guard core-image-allocation core-image-lifetime core-image-generation dmabuf-required dmabuf-hints dmabuf-preserved completion-interval completion-submit-failure completion-query-failure completion-gl-failure completion-retained completion-render completion-ordered egl-surface-colorspace egl-surface-resolvers egl-surface-operations egl-surface-pixmap egl-surface-client-buffer platform-window-core platform-window-ext platform-window-invalid platform-window-wide platform-window-guard platform-window-render pbuffer-grid pbuffer-basic pbuffer-zero pbuffer-invalid pbuffer-guard pbuffer-limits pbuffer-pressure pbuffer-unknown surface-limits-unbound surface-limits-reject surface-limits-current surface-limits-generation surface-limits-render egl-no-renderer raw-discard-recover raw-discard-block raw-discard-query raw-discard-peer raw-discard-last raw-discard-malloc raw-discard-record raw-discard-unknown-before raw-discard-unknown-after raw-discard-render raw-reserved-name raw-flush-reject raw-publication-order shared-create-rollback shared-records-render shared-name-order shared-name-cancel shared-imag