for case_name in ${KANDELO_GRAPHICS_LIBC_CASES:-$default_cases}; do
    python3 - "$output_dir/image-ownership" "$case_name" <<'PYTHON' || status=1
import os, subprocess, sys
command = sys.argv[1:]
if sys.argv[2] == "encoder-inline-export":
    output = os.environ.get("KANDELO_GRAPHICS_INLINE_EXPORT")
    if not output:
        raise SystemExit("encoder-inline-export requires KANDELO_GRAPHICS_INLINE_EXPORT output path")
    command.append(output)
try:
    result = subprocess.run(command, timeout=30)
except subprocess.TimeoutExpired:
    print("FAIL: native graphics case timed out: " + sys.argv[2], flush=True)
    sys.exit(1)
if result.returncode < 0:
    print("FAIL: native graphics case " + sys.argv[2] + " terminated by signal " + str(-result.returncode), flush=True)
sys.exit(result.returncode if result.returncode >= 0 else 1)
PYTHON
done
exit "$status"
